template<class T> class vector {
    T* begin_;
    T* end_;
    T* capacity_;
public:
    vector() : begin_(0), end_(0), capacity_(0) {}
    void resize(unsigned int n) {
        if (n < (unsigned int)(end_ - begin_)) end_ = begin_ + n;
        else if (n > (unsigned int)(end_ - begin_)) insert(end_, n - (end_ - begin_), T());
    }
    void insert(T*, unsigned int, const T&);
};

